                    'question' => 'Under SECP and KMI-30 Shariah screening guidelines, what is the maximum permissible ratio of interest-bearing debt to total assets?',
                    'options' => ['0% (Zero debt permitted)', 'Less than 37%', 'Exactly 50%', 'Up to 75%'],
